/** Narrow comparison of the CHECK expressions generated by ddl.ts. */
import type { ColumnDescriptor, TableDescriptor } from "../src/schema.ts";
import { type Backend, checkExpression, checkName, quote } from "./ddl.ts";

const tokens = (sql: string) =>
  sql.match(
    /'(?:''|[^'])*'|"(?:""|[^"])*"|::|>=|<=|<>|[A-Za-z_][A-Za-z_0-9]*|\d+|[^\s]/g,
  ) ?? [];

function normalized(sql: string, numeric: boolean): string {
  const parts = tokens(sql), result: string[] = [];
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i]!;
    if (
      part === "::" &&
      ["text", "bigint", "integer", "numeric"].includes(
        parts[i + 1]?.toLowerCase() ?? "",
      )
    ) {
      i++;
      continue;
    }
    if (part === "(" || part === ")") continue;
    if (part.startsWith('"')) {
      result.push(part.slice(1, -1).replaceAll('""', '"'));
    } else if (numeric && /^'-?\d+'$/.test(part)) {
      result.push(
        ...(part.startsWith("'-")
          ? ["-", part.slice(2, -1)]
          : [part.slice(1, -1)]),
      );
    } else result.push(part.startsWith("'") ? part : part.toLowerCase());
  }
  const expression = result.join(" ");
  return numeric
    ? expression
    : expression.replace(/'(?:''|[^'])*'(?: , '(?:''|[^'])*')+/g, (values) =>
      (values.match(/'(?:''|[^'])*'/g) ?? []).sort().join(" , "));
}

function expected(backend: Backend, c: ColumnDescriptor): string {
  if (backend === "postgresql") {
    const name = quote(c.name);
    if (c.logical_type === "enum") {
      const values = c.enum_values!.map((v) => `'${v.replaceAll("'", "''")}'`);
      return values.length === 1
        ? `${name} = ${values[0]}`
        : `${name} = ANY (ARRAY[${values.join(", ")}])`;
    }
    if (c.logical_type === "integer" || c.logical_type === "decimal") {
      const max = c.logical_type === "integer"
        ? "9007199254740991"
        : "9".repeat(c.precision!);
      return `${name} >= -${max} AND ${name} <= ${max}`;
    }
  }
  return checkExpression(backend, c);
}

export function checkDifferences(
  backend: Backend,
  descriptor: TableDescriptor,
  actual: Record<string, string>,
): string[] {
  const remaining = new Set(Object.keys(actual)), differences: string[] = [];
  for (const c of descriptor.columns) {
    if (!checkExpression(backend, c)) continue;
    const name = checkName(descriptor.table_id, c.name), found = actual[name];
    remaining.delete(name);
    if (found === undefined) {
      differences.push(`missing check constraint ${name}`);
    } else if (
      normalized(found, c.logical_type !== "enum") !==
        normalized(expected(backend, c), c.logical_type !== "enum")
    ) differences.push(`check constraint ${name} expression differs`);
  }
  for (const name of remaining) {
    differences.push(`unexpected check constraint ${name}`);
  }
  return differences;
}

export function sqliteChecks(sql: string): Record<string, string> {
  const parts = tokens(sql), result: Record<string, string> = {};
  for (let i = 0; i < parts.length; i++) {
    if (parts[i]?.toLowerCase() !== "check") continue;
    if (
      parts[i - 2]?.toLowerCase() !== "constraint" ||
      !parts[i - 1]?.startsWith('"') || parts[i + 1] !== "("
    ) throw new Error("unsupported unnamed CHECK constraint");
    const name = parts[i - 1]!.slice(1, -1).replaceAll('""', '"');
    let depth = 1, end = i + 2;
    for (; end < parts.length && depth; end++) {
      if (parts[end] === "(") depth++;
      if (parts[end] === ")") depth--;
    }
    if (depth || Object.hasOwn(result, name)) {
      throw new Error("invalid physical CHECK definition");
    }
    result[name] = parts.slice(i + 2, end - 1).join(" ");
    i = end - 1;
  }
  return result;
}
